<script setup lang="ts">
import type {IssueDto,PhotoUploadDto} from '~/types/api'
import {errorMessage,todayLocal} from '~/utils/format'
const props=defineProps<{issue:IssueDto}>(),emit=defineEmits<{saved:[]}>()
const open=ref(false),busy=ref(false),uploading=ref(false),failed=ref(false),error=ref(''),kind=ref('progress'),date=ref(todayLocal()),notes=ref(''),deadline=ref(''),unit=ref(''),follower=ref(''),photos=ref<PhotoUploadDto[]>([])
interface History{id:string;at:string;action:string;after:string}
const history=ref<History[]>([]), revision=ref(0), staff=ref<string[]>([])
const followerOptions=computed(()=>[...new Set([...staff.value,...(follower.value?[follower.value]:[])])])
onMounted(async()=>{try{staff.value=(await $fetch<{name:string}[]>('/api/records/staff')).map(x=>x.name)}catch(e){error.value=errorMessage(e)}})
const kinds=[{label:'跟进记录',value:'progress'},{label:'转交单位',value:'transfer'},{label:'延长期限',value:'extend'},{label:'安排跟进人',value:'assign'}]
function summary(item:History){try{const data=JSON.parse(item.after);return [data.date,data.notes,data.kind==='extend'?`新期限 ${data.deadline}`:'',data.kind==='transfer'?`转交 ${data.responsibleUnit}`:'',data.follower?`跟进人 ${data.follower}`:''].filter(Boolean).join(' · ')}catch{return item.after}}
async function load(){try{history.value=await $fetch(`/api/history/${props.issue.id}`)}catch(e){error.value=errorMessage(e)}}
async function save(){if(busy.value||uploading.value||failed.value)return;if(kind.value==='extend'&&deadline.value<=props.issue.deadline){error.value='新的期限应晚于原期限';return}if(kind.value==='transfer'&&!unit.value.trim()){error.value='请填写接收单位';return}if(kind.value==='assign'&&!follower.value.trim()){error.value='请填写跟进人员';return}if(!notes.value.trim()){error.value='请填写办理说明';return}busy.value=true;error.value='';try{await $fetch(`/api/issues/${props.issue.id}/operations`,{method:'POST',body:{revision:revision.value,kind:kind.value,date:date.value,notes:notes.value,deadline:deadline.value,responsibleUnit:unit.value,follower:follower.value,photoIds:photos.value.map(x=>x.id)},retry:0});open.value=false;notes.value='';photos.value=[];await load();emit('saved')}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
function begin(){revision.value=props.issue.revision;kind.value='progress';date.value=todayLocal();notes.value='';photos.value=[];failed.value=false;error.value='';follower.value=props.issue.follower??'';deadline.value=props.issue.deadline;unit.value=props.issue.responsibleUnit;open.value=true}
function close(){if(busy.value||uploading.value)return;if((notes.value.trim()||photos.value.length)&&!window.confirm('办理内容尚未保存，放弃填写吗？'))return;open.value=false}
watch(()=>props.issue.id,()=>{open.value=false;void load()},{immediate:true})
</script>
<template><div class="mt-3"><p v-if="issue.follower" class="text-sm mb-2">跟进人：{{issue.follower}}</p><UButton v-if="!issue.voided && issue.status!=='closed'" label="办理进度" color="neutral" variant="outline" @click="begin" /><div v-for="item in history" :key="item.id" class="mt-3 border-l-2 border-default pl-3"><strong class="text-sm">{{item.action}}</strong><p class="text-sm text-muted">{{summary(item)}}</p></div><UModal :open="open" title="办理进度" :dismissible="!busy&&!uploading" :close="!busy&&!uploading" @update:open="value=>{if(!value)close()}"><template #body><div class="space-y-4"><UAlert v-if="error" :description="error" color="error" /><UFormField label="办理方式"><USelect v-model="kind" :items="kinds" class="w-full" :disabled="busy||uploading" /></UFormField><UFormField label="办理日期"><UInput v-model="date" type="date" :min="issue.inspectionDate" :max="todayLocal()" :disabled="busy" /></UFormField><UFormField v-if="kind==='extend'" label="新的期限" required><p class="text-sm text-muted mb-2">原期限 {{issue.deadline}}</p><UInput v-model="deadline" type="date" :min="issue.deadline" :disabled="busy" /></UFormField><UFormField v-if="kind==='transfer'" label="接收单位" required><UInput v-model="unit" class="w-full" :disabled="busy" /></UFormField><UFormField label="社区跟进人员" :required="kind==='assign'"><USelectMenu v-if="staff.length" v-model="follower" :items="followerOptions" create-item :disabled="busy" placeholder="选择或输入姓名" class="w-full" @create="value=>{follower=value.trim()}"><template #create-item-label="{item}">使用姓名：{{item}}</template></USelectMenu><NameTagsInput v-else v-model="follower" :disabled="busy" class="w-full" /></UFormField><UFormField label="办理说明" required><UTextarea v-model="notes" class="w-full" :rows="3" :disabled="busy" /></UFormField><UFormField label="现场照片"><PhotoUploader v-model="photos" phase="site" :disabled="busy" @busy="uploading=$event" @failed="failed=$event" /></UFormField></div></template><template #footer><UButton label="取消" color="neutral" variant="outline" :disabled="busy||uploading" @click="close" /><UButton label="保存办理记录" :loading="busy" :disabled="uploading||failed" @click="save" /></template></UModal></div></template>
